from lib import *
S = SS('h42')
steps = [
    step("grpc-go 自带的日志用环境变量控制,输出到 stderr。同一个小程序(连一个不存在的服务、正常调用、失败调用、关闭)在不同设置下:不设置:0 行;GRPC_GO_LOG_SEVERITY_LEVEL=error:0 行;=warning:1 行(1 条 WARNING:“[core] [Channel #7 SubChannel #8] grpc: addrConn.createTransport failed to connect to {Addr: …}. Err: connection…”——连不上服务,只在 WARNING 级别才看得见);=info:94 行,共 42 条日志(INFO 41、WARNING 1;一条日志可能有多行);再加 GRPC_GO_LOG_VERBOSITY_LEVEL=2:158 行,共 50 条(INFO 49、WARNING 1);verbosity 设成 99 与 2 完全一样(没有更详细的级别)。所以默认情况下连不上服务也看不到任何输出,排查连接问题要先把级别调到 warning 或 info。", t=tl(S(1)), done=lidx(S(1), 'VERBOSITY_LEVEL=99'), mark=lidx(S(1), 'SEVERITY_LEVEL=warning  '), b=bars([['不设置:日志条数', 0, '0'], ['warning:条数', 1, '1'], ['info:条数', 42, '42'], ['info + verbosity 2:条数', 50, '50']], 55, mark=[1], done=[0, 2, 3]), kv=KV([['默认 / error', '0 条,连不上也看不到'], ['warning', '1 条:连接失败'], ['info(+ verbosity 2)', '42 条(50 条)']], ['warning'])),
    step("INFO 级别日志里是什么:前几行是“[core] [Server #1] Server created”“original dial target is: \"127.0.0.1:9800\"”“[Channel #2] Channel created for target …”“parsed dial target is: resolver.Target{URL:url.URL{Scheme:\"dns\", …”(解析成 dns 解析器)“Channel authority set to …”“Channel Connectivity change to CONNECTING”——通道创建、解析、状态变化都有,这些带编号的 [Channel #2] [SubChannel #8] 可以和 channelz 对上。设 GRPC_GO_LOG_FORMATTER=json 后每条日志是一行 JSON({\"message\":…,\"severity\":\"INFO\"}),共 42 行(一条日志一行,没有续行),便于日志系统采集。", t=tl(S(2)), done=lidx(S(2), 'GRPC_GO_LOG_FORMATTER=json:共'), mark=lidx(S(2), 'GRPC_GO_LOG_SEVERITY_LEVEL=info:共'), b=bars([['info 文本格式:行数', 94, '94'], ['info JSON 格式:行数', 42, '42']], 100, mark=[0], done=[1]), kv=KV([['文本格式', '一条日志可能多行(94 行 = 42 条)'], ['JSON 格式', '一条日志一行(42 行)'], ['编号', '[Channel #2] 等,可与 channelz 对应']], ['JSON 格式'])),
    step("用自己的 logger:grpclog.SetLoggerV2 必须在使用 grpc 之前调用(它不是并发安全的)。同一个小程序里,让 V(2) 返回 true,自定义 logger 收到:INFO 49 条、WARNING 1 条——和环境变量 verbosity=2 的条数(INFO 49、WARNING 1)完全一致。这样可以把 grpc 的日志接到你自己的日志库里(带上自己的字段、采样、级别),而不是只能写 stderr。", t=tl(S(3)), done=lidx(S(3), '自定义 logger 收到'), mark=lidx(S(3), '自定义 logger 收到'), b=bars([['自定义 logger 收到 INFO 条数', 49, '49'], ['WARNING 条数', 1, '1']], 55, done=[0, 1]), kv=KV([['设置', 'grpclog.SetLoggerV2(...),在使用 grpc 之前'], ['V(2)=true', 'INFO 49 条 + WARNING 1 条'], ['与环境变量', 'verbosity=2 条数一致']], ['设置'])),
    step("channelz:服务端注册 channelz 服务后,可以问“有哪些通道、连接,调用成功失败各多少”(包 google.golang.org/grpc/channelz/service,这里用同进程的客户端读它)。客户端 100 次成功 + 5 次失败(Internal)之后:通道 #1 状态 READY,调用 开始 105、成功 100、失败 5;通道 #2 是我用来查询 channelz 的连接,调用开始 1;服务端 调用 开始 107、成功 101、失败 5(多出来的 2 次开始、1 次成功是 channelz 查询本身)。再看服务端的连接(socket)层:连接 #1 流 开始 105、成功 105、失败 0;收到消息 105、发出消息 100——注意 5 次失败的 RPC 在“流”层面仍然算“成功”(HTTP/2 流正常结束,错误在 grpc-status 里),发出的消息比收到的少 5 条(失败调用没有响应消息)。排查时要分清 RPC 层的失败和流/连接层的失败。", t=tl(S(4)), done=lidx(S(4), '服务端连接 #1'), mark=lidx(S(4), '通道 #1'), b=bars([['客户端通道 #1:开始', 105, '105'], ['成功', 100, '100'], ['失败', 5, '5'], ['服务端连接 #1:流成功', 105, '105']], 110, mark=[2], done=[0, 1, 3]), kv=KV([['RPC 层', '开始 105、成功 100、失败 5'], ['流层(连接 #1)', '开始 105、成功 105、失败 0'], ['消息', '收到 105、发出 100(失败调用没有响应)']], ['流层(连接 #1)'])),
]
A = mkarth('h42', 42, 'gRPC,日志,GRPC_GO_LOG_SEVERITY_LEVEL,grpclog,channelz,调试,Go,真实验证,动画演示',
    '实测 grpc-go 的日志与调试:默认连不上服务也没有任何输出,要 GRPC_GO_LOG_SEVERITY_LEVEL=warning 才看到连接失败;info 级别 42 条、verbosity=2 为 50 条;JSON 格式;grpclog.SetLoggerV2 接入自己的日志;channelz 里 RPC 层失败与流层成功的区别。',
    'gRPC 出问题时怎么看日志?环境变量怎么设?日志里有什么?怎么接到自己的日志库?channelz 能告诉你什么?这篇用同一个小程序在不同设置下把输出都抓下来对比。',
    [('默认 0 条', '不设置环境变量时,连不上服务也没有任何日志输出'), ('42 条 → 50 条', 'INFO 级别与再加 verbosity=2 的日志条数'), ('流层 105 成功 / RPC 层 5 失败', 'channelz 里同样的调用在流层面全部成功,在 RPC 层有 5 次失败')],
    [('环境变量', '<p>GRPC_GO_LOG_SEVERITY_LEVEL 取 error、warning、info,GRPC_GO_LOG_VERBOSITY_LEVEL 取数字(2 就是最详细),GRPC_GO_LOG_FORMATTER=json 输出 JSON。默认不输出,连不上服务也看不到。</p>'),
     ('日志内容', '<p>通道创建、目标解析、状态变化、子连接创建和失败,带 [Channel #N] [SubChannel #M] 编号。</p>'),
     ('接到自己的日志库', '<p>grpclog.SetLoggerV2 设置自己的 logger,必须在使用 grpc 之前调用。</p>'),
     ('channelz', '<p>注册 channelz 服务后可以查通道、子通道、连接和服务器的调用/流/消息计数。注意 RPC 层与流层的区别:返回错误状态的 RPC 在流层面仍算成功。</p>')],
    steps,
    [ENV_H + '。日志数据来自子进程的 stderr,行数和条数用代码统计(日志条数按“以日期开头的行”数,续行不算);“verbosity 99 与 2 相同”只比较了条数;channelz 查询用的是同进程里另一条连接,所以结果里包含查询自身的调用',
     '没有验证:error 级别下是否会有 ERROR 输出(这个小程序没触发);GRPC_GO_LOG_SEVERITY_LEVEL 取其它值的行为;日志对性能的影响;stats.Handler 与 OpenTelemetry(另一类可观测手段);channelz 的 Web 界面(grpc-zpages 类工具);GODEBUG / pprof 对 goroutine 泄漏的排查(第 31、35 篇有相关数字)'],
    '日志与调试')
